use moloch_replay::{engine::Engine,session::Session};
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{fs,path::PathBuf,sync::atomic::{AtomicU64,Ordering}};
const BASE:i64=1_792_054_800_000;
fn iso(t:i64)->String{chrono::DateTime::from_timestamp_millis(BASE+t).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn hash(v:&Value)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
struct F{root:PathBuf,bank:Option<Session>,policy:Value,seed:Value}
impl Drop for F{fn drop(&mut self){self.bank.take();let _=fs::remove_dir_all(&self.root);}}
impl F{
 fn new(changes:Value)->Self{static N:AtomicU64=AtomicU64::new(0);let root=std::env::temp_dir().join(format!("ordinary-exclusions-{}-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos(),N.fetch_add(1,Ordering::Relaxed)));fs::create_dir(&root).unwrap();let mut policy=json!({"initialCash":"100.000000","maximumCommitted":"40.000000","maximumMarketCost":"10.000000","quantity":5,"maximumMarkets":3,"entryStopAt":iso(120000)});for(k,v)in changes.as_object().unwrap(){policy[k]=v.clone();}let seed=json!({"runId":"exclusion-fixture","availableCash":"100.000000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(0)});let bank=Session::open_live(&root.join("bank"),&policy,&seed).unwrap();Self{root,bank:Some(bank),policy,seed}}
 fn b(&self)->&Session{self.bank.as_ref().unwrap()}
 fn put(&mut self,e:&Value)->std::result::Result<bool,Box<dyn std::error::Error>>{let seq=self.b().last_source_sequence("fixture")+1;self.bank.as_mut().unwrap().accept("fixture",seq,e)}
 fn event(&self,ids:Value,at:i64)->Value{json!({"type":"ordinary_entry_exclusions_v1","source":"moloch_live_dispatcher","receivedAt":iso(at),"processedAt":iso(at),"bankScope":{"runId":"exclusion-fixture","bankManifestHash":self.b().manifest_hash(),"tournamentId":"cup"},"bankHead":self.b().durable_head(),"expectedReportSha256":hash(&self.b().engine().report().unwrap()),"managedExchangeIds":ids,"approvedReviewSetSha256":"b".repeat(64),"controlSha256":"c".repeat(64),"expectedPreviousExclusionSha256":self.b().engine().ordinary_entry_exclusion_record().map_or(Value::Null,|v|v["sha256"].clone())})}
 fn install(&mut self,ids:Value,at:i64){let e=self.event(ids,at);self.put(&e).unwrap();}
 fn book(&mut self,ex:&str,at:i64){self.put(&json!({"type":"book","receivedAt":iso(at),"book":{"marketId":ex,"exchangeId":ex,"tournamentId":"cup","sequence":(at+1).to_string(),"sourceAt":iso(at),"requestStartedAt":iso(at),"receivedAt":iso(at),"bids":[{"price":"0.400000","quantity":100}],"asks":[{"price":"0.450000","quantity":100}]}})).unwrap();}
 fn retire_unsent(&mut self,at:i64){for q in self.b().engine().order_records().into_iter().filter(|q|q["retired"]==false){self.put(&json!({"type":"unsubmitted_intent_retired","source":"moloch_live_dispatcher","orderId":q["id"],"receiptHash":"d".repeat(64),"confirmedNetworkAttempts":0,"deferPlanningForPackage":true,"receivedAt":iso(at)})).unwrap();}}
}
#[test]fn default_has_no_report_field_or_planning_change(){let mut f=F::new(json!({}));assert!(f.b().engine().ordinary_entry_exclusions().is_empty());assert!(f.b().engine().report().unwrap().get("ordinaryEntryExclusions").is_none());f.book("101",0);assert!(f.b().engine().order_records().iter().any(|q|q["action"]=="buy"));}
#[test]fn excluded_flat_market_does_not_reserve_cash_or_take_only_fresh_slot(){let mut f=F::new(json!({"maximumMarkets":1}));f.install(json!(["101"]),0);f.book("101",1);assert!(f.b().engine().order_records().is_empty());assert_eq!(f.b().engine().report().unwrap()["reservedCash"],"0.000000");f.book("102",2);assert!(f.b().engine().order_records().iter().any(|q|q["exchangeId"]=="102"));assert!(f.b().engine().fills().is_empty());}
#[test]fn install_is_not_cancellation_or_cash_release_and_retired_drafts_stay_retired(){let mut f=F::new(json!({}));f.book("101",0);let qs=f.b().engine().order_records();let cash=f.b().engine().report().unwrap()["reservedCash"].clone();f.install(json!(["101"]),1);assert_eq!(f.b().engine().order_records(),qs);assert_eq!(f.b().engine().report().unwrap()["reservedCash"],cash);f.book("101",3000);assert_eq!(f.b().engine().order_records(),qs);f.retire_unsent(3001);f.book("101",6000);assert!(f.b().engine().order_records().iter().all(|q|q["retired"]==true));assert_eq!(f.b().engine().report().unwrap()["reservedCash"],"0.000000");}
#[test]fn original_physical_ack_cannot_be_abandoned_by_exclusion(){let mut f=F::new(json!({}));f.book("101",0);let q=f.b().engine().order_records()[0].clone();f.put(&json!({"type":"actual_order_ack","source":"official_sig_api_v1","receiptHash":"a".repeat(64),"orderId":q["id"],"actualOrderId":"901","marketId":q["marketId"],"exchangeId":q["exchangeId"],"side":q["side"],"action":q["action"],"quantity":q["quantity"],"price":q["price"],"receivedAt":iso(3000)})).unwrap();f.install(json!(["101"]),3001);let before=f.b().engine().report().unwrap();assert!(f.put(&json!({"type":"unsubmitted_intent_retired","source":"moloch_live_dispatcher","orderId":q["id"],"receiptHash":"d".repeat(64),"confirmedNetworkAttempts":0,"receivedAt":iso(3002)})).is_err());assert_eq!(f.b().engine().report().unwrap(),before);assert!(f.b().engine().fills().is_empty());}
#[test]fn reviewed_entry_can_reserve_excluded_market_under_original_caps(){let mut f=F::new(json!({"requireCurrentFlow":true,"minimumSpreadTicks":1000}));f.install(json!(["101"]),0);f.book("101",1);let e=json!({"type":"reviewed_fundamental_entry_reserved_v1","source":"moloch_live_dispatcher","bankScope":{"runId":"exclusion-fixture","bankManifestHash":f.b().manifest_hash(),"tournamentId":"cup"},"bankHead":f.b().durable_head(),"expectedReportSha256":hash(&f.b().engine().report().unwrap()),"originSha256":"a".repeat(64),"reviewSha256":"b".repeat(64),"bookSha256":hash(&f.b().engine().live_package_books()[0]),"reviewCurrentUntilMs":BASE+120000,"marketId":"101","exchangeId":"101","side":"YES","limitPrice":"0.400000","expectedPayout":"0.600000","marginPerShare":"0.010000","reviewMaximumQuantity":5,"reviewMaximumPrincipal":"1.100000","expiresAt":iso(60000),"receivedAt":iso(3000),"processedAt":iso(3000)});f.put(&e).unwrap();let qs=f.b().engine().order_records();assert_eq!(qs.len(),1);assert_eq!(qs[0]["quantity"],2);assert!(qs[0].get("reviewedFundamentalEntry").is_some());assert_eq!(f.b().engine().report().unwrap()["reservedCash"],"0.800000");}
#[test]fn set_updates_are_chained_and_same_set_preserves_historical_audit(){let mut f=F::new(json!({}));f.install(json!(["101"]),0);let first=f.b().engine().ordinary_entry_exclusion_record().unwrap();let mut same=f.event(json!(["101"]),1);same["controlSha256"]=json!("e".repeat(64));same["approvedReviewSetSha256"]=json!("f".repeat(64));f.put(&same).unwrap();assert_eq!(f.b().engine().ordinary_entry_exclusion_record().unwrap(),first);f.install(json!(["101","102"]),2);let second=f.b().engine().ordinary_entry_exclusion_record().unwrap();assert_eq!(second["revision"],2);assert_eq!(second["previousSha256"],first["sha256"]);let mut stale=f.event(json!([]),3);stale["expectedPreviousExclusionSha256"]=first["sha256"].clone();assert!(f.put(&stale).is_err());f.install(json!([]),3);assert!(f.b().engine().ordinary_entry_exclusions().is_empty());f.book("101",4);assert!(!f.b().engine().order_records().is_empty());}
#[test]fn source_scope_head_report_hashes_sorted_ids_and_future_receipt_fail_atomically(){for case in ["source","run","manifest","head","report","hash","duplicate","unsorted","numeric","zero","received","missing_previous"]{let mut f=F::new(json!({}));let mut e=f.event(json!(["101"]),0);match case{"source"=>e["source"]=json!("other"),"run"=>e["bankScope"]["runId"]=json!("other"),"manifest"=>e["bankScope"]["bankManifestHash"]=json!("0".repeat(64)),"head"=>e["bankHead"]["previous"]=json!("0".repeat(64)),"report"=>e["expectedReportSha256"]=json!("0".repeat(64)),"hash"=>e["controlSha256"]=json!("invalid"),"duplicate"=>e["managedExchangeIds"]=json!(["101","101"]),"unsorted"=>e["managedExchangeIds"]=json!(["102","101"]),"numeric"=>e["managedExchangeIds"]=json!([101]),"zero"=>e["managedExchangeIds"]=json!(["01"]),"received"=>e["receivedAt"]=json!(iso(1)),_=>{e.as_object_mut().unwrap().remove("expectedPreviousExclusionSha256");}}let head=f.b().durable_head();let report=f.b().engine().report().unwrap();assert!(f.put(&e).is_err(),"{case}");assert_eq!(f.b().durable_head(),head,"{case}");assert_eq!(f.b().engine().report().unwrap(),report,"{case}");}}
#[test]fn paper_engine_cannot_install_live_exclusion(){let f=F::new(json!({}));let mut e=Engine::new(&f.policy).unwrap();let before=e.report().unwrap();assert!(e.advance(&f.event(json!(["101"]),0)).is_err());assert_eq!(e.report().unwrap(),before);}
#[test]fn actual_journal_restart_preserves_revision_orders_and_financial_report(){let mut f=F::new(json!({}));f.install(json!(["101"]),0);f.book("101",1);f.book("102",2);f.install(json!(["101","103"]),3);let report=f.b().engine().report().unwrap();let orders=f.b().engine().order_records();let head=f.b().durable_head();f.bank.take();let bank=Session::open_live(&f.root.join("bank"),&f.policy,&f.seed).unwrap();assert_eq!(bank.engine().report().unwrap(),report);assert_eq!(bank.engine().order_records(),orders);assert_eq!(bank.durable_head(),head);assert_eq!(bank.engine().ordinary_entry_exclusions().into_iter().collect::<Vec<_>>(),vec!["101","103"]);}
#[test]fn inherited_owned_sell_management_survives_exclusion(){let mut f=F::new(json!({"inventoryExitMode":"fixedGain","inventoryMinimumGain":"0.005000","maximumInventoryAgeMs":60000}));f.put(&json!({"type":"actual_position_adoption","source":"official_sig_api_v1","authority":"human_moloch_inherited_management_20261015","complete":true,"receiptHash":"a".repeat(64),"tournamentId":"cup","receivedAt":iso(0),"requestStartedAt":iso(0),"openingCost":"1.000000","effectiveMaximumMarkets":4,"positions":[{"marketId":"101","exchangeId":"101","quantity":5,"lots":[{"lotId":"900","quantity":5,"side":"YES","entryPrice":"0.200000","openedAt":iso(-1000)}],"lotPrincipal":"1.000000","reportedCostBasis":"1.000000","reportedMinusLotPrincipal":"0.000000","basisClassification":"exact"}]})).unwrap();f.install(json!(["101"]),0);f.book("101",1);let qs=f.b().engine().order_records();assert!(qs.iter().any(|q|q["exchangeId"]=="101"&&q["action"]=="sell"&&q["side"]=="YES"));assert_eq!(f.b().engine().wallet.quantity("101",moloch_replay::Side::Yes),5);assert!(f.b().engine().fills().is_empty());}
#[test]fn standalone_seed_cannot_silently_drop_installed_exclusions(){let mut f=F::new(json!({}));f.install(json!(["101"]),0);let report=f.b().engine().report().unwrap();assert!(matches!(Engine::from_seed_state(&report),Err("SEED_ORDINARY_ENTRY_EXCLUSIONS_REQUIRE_REPLAY")));}
